svg.desc:
# Generated by mscgen_js - https://sverweij.github.io/mscgen_js

  #This is the default signalling chart.
#Edit and press F2 to see the result.
#You can change the default chart
#with the leftmost button on the Preferences pane of the ribbon.
# GOTO:https://mscgen.js.org/
msc {
hscale = "1.5";

CLI_A [label="CLI HostA",linecolor="blue",arclinecolor="blue"],
APP_A [label="App HostA\n(client)",linecolor="blue",arclinecolor="blue"],
CTRL_A [label="Controller A",linecolor="orange",arclinecolor="orange"],
CTRL_B [label="Controller B",linecolor="orange",arclinecolor="orange"],
APP_B [label="App HostB\n(server)",linecolor="blue",arclinecolor="blue"];

CLI_A=>APP_A [label="'range' command"];
APP_A=>CTRL_A[label="CS_Procedure_Enable\n HCI command",linecolor="orange"];
CTRL_A=>CTRL_B[label="LL_CS_REQ"];
CTRL_B=>CTRL_A[label="LL_CS_RSP"];
CTRL_A=>CTRL_B[label="LL_CS_IND"];
CTRL_A box CTRL_B[label="CS Procedure"];
CTRL_A=>APP_A[label="CS_Event_Result\n HCI event"],
CTRL_B=>APP_B[label="CS_Event_Result\n HCI event"];
CTRL_A=>APP_A[label="CS_Event_Result_Continue\n HCI event"],
CTRL_B=>APP_B[label="CS_Event_Result_Continue\n HCI event"];
...;
CTRL_A=>APP_A[label="CS_Event_Result_Continue\n HCI event"],
CTRL_B=>APP_B[label="CS_Event_Result_Continue\n HCI event"];
APP_B=>APP_A[label="Data fragment"];
APP_B=>APP_A[label="Data fragment"];
...;
APP_B=>APP_A[label="Data fragment"];
APP_A box APP_A[label="Distance computation"];
APP_A=>CLI_A[label="output result"];
|||;
}
